//! The identity prompt against Node's output (`workflow_actor_golden.json`, generated by calling Node's
//! `buildWorkflowActorIdentitySection` with `includeHarness` and `midConversationSystem` on).

use super::*;

const GOLDEN: &str = include_str!("workflow_actor_golden.json");

fn golden(case: &str) -> String {
    let all: serde_json::Value = serde_json::from_str(GOLDEN).expect("golden json");
    all[case].as_str().expect("case").to_owned()
}

#[test]
fn a_named_actor_with_a_persona_matches_node_byte_for_byte() {
    assert_eq!(
        identity(Some("调研员甲"), Some("PERSONA LINE one.\nSecond line.")),
        golden("named")
    );
}

#[test]
fn an_anonymous_actor_without_a_persona_matches_node_byte_for_byte() {
    assert_eq!(identity(None, None), golden("anon"));
}

#[test]
fn the_name_is_trimmed_and_a_blank_persona_is_left_out() {
    assert_eq!(identity(Some("  Ada  "), Some("   ")), golden("nameOnly"));
}
